const fs = require('fs');

class CodeforcesC {

    constructor() {
        this.ONLINE_JUDGE = process.env['ONLINE_JUDGE'] !== undefined;
        this.tokens = [];
        this.pos = 0;
        this.output = [];
        this.DEBUG = false;
        this.timeBegin = 0;
        this.timeEnd = 0;
        this.memoryTotal = 0;
        this.memoryFree = 0;
    }

    init() {
        let data;
        if (this.ONLINE_JUDGE) {
            data = fs.readFileSync(0, 'utf8');
        } else {
            data = fs.readFileSync('input.txt', 'utf8');
        }
        this.tokens = data.split(/\s+/).filter(s => s.length > 0);
        this.pos = 0;
        this.output = [];
    }

    close() {
        const result = this.output.join('\n') + (this.output.length > 0 ? '\n' : '');
        if (this.ONLINE_JUDGE) {
            process.stdout.write(result);
        } else {
            fs.writeFileSync('output.txt', result);
        }
    }

    println(s) {
        this.output.push(String(s));
    }

    readString() {
        if (this.pos >= this.tokens.length) return null;
        return this.tokens[this.pos++];
    }

    readInt() {
        return parseInt(this.readString(), 10);
    }

    readLong() {
        return BigInt(this.readString());
    }

    readDouble() {
        return parseFloat(this.readString());
    }

    time() {
        this.timeEnd = Date.now();
        console.error("Time = " + (this.timeEnd - this.timeBegin));
    }

    memory() {
        this.memoryFree = process.memoryUsage().heapUsed;
        console.error("Memory = " + ((this.memoryTotal - this.memoryFree) >> 10) + " KB");
    }

    debug(...objects) {
        if (this.DEBUG) {
            for (const o of objects) {
                console.error(String(o));
            }
        }
    }

    readIntArray(n) {
        const array = new Array(n);
        for (let i = 0; i < n; i++)
            array[i] = this.readInt();
        return array;
    }

    run() {
        try {
            this.timeBegin = Date.now();
            this.memoryTotal = process.memoryUsage().heapUsed;
            this.init();
            this.solve();
            this.close();
            this.time();
            this.memory();
        } catch (e) {
            console.error(e.stack);
            process.exit(-1);
        }
    }

    solve() {

        const l = this.readInt();
        const r = this.readInt();

        const n = 9;
        const ten = new Array(n + 1);

        ten[0] = 1;

        for (let i = 1; i <= n; i++)
            ten[i] = 10 * ten[i - 1];

        let answer = 0n;

        const luckyNumbers = [];

        for (let length = 1; length <= n; length++) {
            for (let cur = 0; cur < (1 << length); cur++) {
                let value = 0;
                for (let j = 0; j < length; j++) {
                    if (((1 << j) & cur) === (1 << j))
                        value += ten[j] * 7;
                    else
                        value += ten[j] * 4;
                }
                //this.println(value);
                luckyNumbers.push(BigInt(value));
            }
        }

        luckyNumbers.push(4444444444n);

        let lastNumber = BigInt(l);
        const bigL = BigInt(l);
        const bigR = BigInt(r);

        for (const luckyNumber of luckyNumbers) {
            if (luckyNumber > bigR) {
                answer += (bigR - lastNumber + 1n) * luckyNumber;
                break;
            }
            if (luckyNumber >= bigL) {
                answer += (luckyNumber - lastNumber + 1n) * luckyNumber;
                lastNumber = luckyNumber + 1n;
            }
        }

        this.println(answer.toString());
    }
}

new CodeforcesC().run();
